INSERT INTO provider_org (id, country_code, region_id, legal_name, display_name, category, service_tier, verification_state, languages, bio, response_time_hours, response_rate_pct, review_count, avg_rating, status) VALUES
('5793283d-1312-4e54-beda-836541886341','MA','a02020a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Chauffeur Morocco SARL','Royal Chauffeur Morocco','transfer',4,'verified',ARRAY['en','fr','es'],'Luxury chauffeur service with Mercedes E-Class and V-Class vehicles. Leather interiors, bottled water, phone chargers, and English-speaking drivers in suits.',8,89.8,42,4.3,'active'),
('939dd6d6-5915-42f1-bdf7-b296667baea1','MA','a02020a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','ONCF — Office National des Chemins de Fer SARL','ONCF — Office National des Chemins de Fer','transfer',2,'verified',ARRAY['en','fr','ar'],'Morocco''s national railway operator. High-speed Al Boraq trains connect Tangier to Casablanca via Rabat in under 3 hours. Conventional trains serve Casablanca, Rabat, Fès, Meknès, Marrakech, Tangier, and Oujda. Book at gare.oncf.ma or at any train station.',2,98,4235,4.1,'active'),
('0a2ee9a9-816a-4107-9e89-537494b824b4','MA','a02020a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','El Jadida Shuttle Express — Station Pickup SARL','El Jadida Shuttle Express — Station Pickup','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers. We also offer ONCF station pickup and drop-off services.',1.5,94,35,4.2,'active'),
('c6647d89-78ad-43fb-b133-0da11a1cf86f','MA','a02020a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Private Transfers — Station Pickup SARL','Atlas Private Transfers — Station Pickup','transfer',3,'verified',ARRAY['en','fr','ar'],'Private door-to-door transfers with professional drivers and modern sedan cars. Flight tracking, meet-and-greet at the airport, and 24/7 availability. We also offer ONCF station pickup and drop-off services.',1.5,94,146,4.2,'active'),
('0c1c7b16-d4c4-49db-ba3c-4a6cb0de139e','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Asilah Heritage Walks SARL','Asilah Heritage Walks','tour',2,'verified',ARRAY['en','fr','ary-Latn'],'A family-run walking tour company founded in 2009. We specialize in intimate small-group tours of historic quarters, led by licensed local guides who grew up in these streets.',8.7,96.5,104,4.5,'active'),
('065d66bf-f23d-4dc5-8e98-5caad010cdf6','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Cultural Tours SARL','Atlas Cultural Tours','tour',3,'verified',ARRAY['en','fr','de'],'Mid-size cultural tour operator with air-conditioned minibuses and university-trained historians. We cover major landmarks with comfortable logistics.',2.8,90.4,77,4.1,'active'),
('c717d406-eeae-4cbe-9f7e-64b4454f588c','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Concierge Asilah SARL','Royal Concierge Asilah','tour',4,'verified',ARRAY['en','fr','es','it'],'Private luxury touring service with Mercedes vans, art-historian guides, and exclusive access to private palaces and collections not open to the public.',5.8,91.2,259,3.8,'active'),
('13f4096c-93a3-4209-9988-0ec688aefa64','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Local Eyes Asilah SARL','Local Eyes Asilah','guided_experience',1,'verified',ARRAY['en','fr','ary-Latn'],'A collective of young local guides who show you the real city — hidden cafes, street art, and neighborhoods the guidebooks miss. Pay-what-you-want ethos.',5.5,97.4,223,4.9,'active'),
('58548c55-c009-42a4-8bfa-acd4cf054105','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',1,95.6,42,4,'active'),
('c27008ea-5ce5-4a2d-a5fb-4668de71cb28','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',8.4,88.8,422,4.7,'active'),
('1ed5d12c-f479-4bb1-aabe-2ec14e6e4894','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Asilah Cooking School SARL','Dar Asilah Cooking School','workshop',2,'verified',ARRAY['en','fr','ary-Latn'],'A traditional riad kitchen where a local family teaches you to prepare tagine, couscous, and pastries from scratch. Small classes, maximum 6 people.',6.7,89.1,81,4.3,'active'),
('9958fa0c-b6cf-4c55-9c51-03856167f1ae','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Maison des Artisans SARL','Maison des Artisans','workshop',2,'verified',ARRAY['en','fr','ar'],'A cooperative workshop space where master artisans — potters, leatherworkers, zellige cutters — teach their craft in 2-hour hands-on sessions. Materials included.',5.5,91.5,191,4.8,'active'),
('a7601b0f-5016-4763-ac61-93054f184a8b','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atelier Lumière SARL','Atelier Lumière','workshop',4,'verified',ARRAY['en','fr','es'],'A luxury creative studio offering private masterclasses with acclaimed Moroccan artists. Photography, calligraphy, and perfume-making in a beautifully restored medina house.',9.9,88.6,60,4.5,'active'),
('551a9ae4-f556-4149-a607-210e11b67de2','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Asilah Budget SARL','Riad Asilah Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',5,89.9,255,4,'active'),
('46543a81-d60f-42f3-a5b2-c0dbe85d102d','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Asilah Boutique SARL','Dar Asilah Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',5.6,98.4,357,5,'active'),
('faa2f32b-1a20-4aff-9a1e-4a5014a62e34','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Asilah Royal SARL','Palais Asilah Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',2.6,92.2,313,3.9,'active'),
('846036f0-0ff7-4053-9bd0-4ee7263efe49','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Asilah Tours SARL','Street Food Asilah Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',2.1,97.8,29,3.8,'active'),
('a35b7f5e-d97b-48bd-8438-d5d75651e952','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Asilah Family Kitchen SARL','Table Asilah Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',10,96.4,376,4.8,'active'),
('37f360c4-63c3-4589-a31c-6a08b442c131','MA','a03030a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Asilah SARL','Le Salon Asilah','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',5,98.2,295,4.1,'active'),
